import { useEffect, useState } from 'react';
import api from '../api';

function Feed() {
  const [posts, setPosts] = useState([]);

  useEffect(() => {
    api.get('/feed')
      .then(res => setPosts(res.data))
      .catch(() => {});
  }, []);

  return (
    <div>
      <h2>Feed</h2>

      {posts.map(post => (
        <div key={post.post_id}>
          <p>{post.content}</p>
          <hr />
        </div>
      ))}
    </div>
  );
}

export default Feed;
